arguments.command:
python3 -c "
import re, glob
for f in sorted(glob.glob('/workspace/.atomcode/skills/investor_panel/references/group-*.md')):
    lines = open(f).readlines()
    in_members = False
    members = []
    for line in lines:
        if '## 成员' in line:
            in_members = True
            continue
        if in_members and line.startswith('|') and not line.startswith('| 大佬') and not line.startswith('|---'):
            parts = [p.strip() for p in line.split('|')[1:-1]]
            if parts:
                members.append(parts[0])
    print(f.split('/')[-1], len(members), members[:3])
"
